{
  "name": "Binder MK 53 气候箱",
  "name_en": "Binder MK 53 climate chamber",
  "manufacturer": "BINDER",
  "description": "Binder MK 53 是一款实验室气候箱/环境试验箱，用于在受控温度条件下放置样品并进行培养、预处理或稳定性测试。该设备具备温度设定与监测功能，并可反馈门状态和运行模式等基本状态信息。",
  "description_en": "The Binder MK 53 is a laboratory climate chamber used to hold samples under controlled temperature conditions for incubation, conditioning, and stability testing. It supports temperature setpoint control and monitoring, and provides basic status information such as door state and operating mode.",
  "tag_hints": [
    "climate chamber",
    "environmental testing",
    "temperature control",
    "sample incubation",
    "stability testing",
    "laboratory oven chamber"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化气候箱通信与操作地址配置。",
      "description_en": "Initialize the climate chamber communication and operation address configuration."
    },
    {
      "action_name": "auto-get_temperature",
      "description": "获取箱体当前温度。",
      "description_en": "Get the current chamber temperature."
    },
    {
      "action_name": "auto-get_temperature_target",
      "description": "获取温度设定值。",
      "description_en": "Get the temperature setpoint."
    },
    {
      "action_name": "auto-get_door_open",
      "description": "获取箱门是否打开。",
      "description_en": "Get whether the chamber door is open."
    },
    {
      "action_name": "auto-get_mode",
      "description": "获取当前运行模式。",
      "description_en": "Get the current operating mode."
    },
    {
      "action_name": "auto-set_temperature",
      "description": "设置温度设定值。",
      "description_en": "Set the temperature setpoint."
    },
    {
      "action_name": "auto-read",
      "description": "读取设备寄存器数据。",
      "description_en": "Read device register data."
    },
    {
      "action_name": "auto-write",
      "description": "写入设备寄存器值。",
      "description_en": "Write a device register value."
    }
  ]
}

